-- 기존 팀 DB용 데이터 패치. 전체 DDL/전체 init_auth_data는 실행하지 않는다.
-- 먼저 11-02_01_SCHEMA_PATCH.sql을 완료한다. 이 파일은 빠진 공통 코드만 넣고 12개 USE_YN을 Y로 맞춘다.
-- 예외 발생 시 이 연결의 미커밋 변경을 ROLLBACK하고 중단한다. 자동 COMMIT하지 않는다.
SET DEFINE OFF
SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

DECLARE
