    SELECT 'CAPACITY_STATUS', NULL, '증설 신청 상태', '추가 이용 인원 신청의 승인·결제 처리 상태', 'N', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='CAPACITY_STATUS');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'CAP_REQUESTED', 'CAPACITY_STATUS', '신청', '추가 인원 사용을 신청한 상태', 'N', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='CAP_REQUESTED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'CAP_APPROVED', 'CAPACITY_STATUS', '승인', '운영자가 증설을 승인하고 결제를 기다리는 상태', 'N', 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='CAP_APPROVED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'CAP_REJECTED', 'CAPACITY_STATUS', '반려', '운영자가 증설 신청을 반려한 상태', 'N', 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='CAP_REJECTED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'CAP_PAID', 'CAPACITY_STATUS', '결제 완료', '증설 결제가 승인되고 인원 한도가 반영된 상태', 'N', 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='CAP_PAID');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'CAP_EXPIRED', 'CAPACITY_STATUS', '기한 만료', '승인 후 결제 가능 기한이 지난 상태', 'N', 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='CAP_EXPIRED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SUPPORT_STATUS', NULL, '장애 지원 상태', '이음 운영자에게 요청한 장애 지원의 진행 상태', 'N', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SUPPORT_STATUS');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SUP_RECEIVED', 'SUPPORT_STATUS', '접수', '장애 지원 문의가 등록된 상태', 'N', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SUP_RECEIVED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SUP_PROCESSING', 'SUPPORT_STATUS', '지원 중', '운영자가 장애를 확인하고 지원하는 상태', 'N', 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SUP_PROCESSING');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SUP_RESOLVED', 'SUPPORT_STATUS', '해결', '장애가 해결된 상태', 'N', 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SUP_RESOLVED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SUP_CLOSED', 'SUPPORT_STATUS', '종료', '장애 지원 처리가 종료된 상태', 'N', 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SUP_CLOSED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SUPPORT_GRANT_STATUS', NULL, '지원 허가 상태', '운영자의 업체 자료 접근 허가 상태', 'N', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SUPPORT_GRANT_STATUS');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SG_REQUESTED', 'SUPPORT_GRANT_STATUS', '허가 요청', '필요한 자료의 접근 허가를 요청한 상태', 'N', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SG_REQUESTED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SG_APPROVED', 'SUPPORT_GRANT_STATUS', '허가 중', '승인된 범위에서 접근할 수 있는 상태', 'N', 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SG_APPROVED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SG_REJECTED', 'SUPPORT_GRANT_STATUS', '허가 반려', '자료 접근 요청이 거절된 상태', 'N', 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SG_REJECTED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SG_REVOKED', 'SUPPORT_GRANT_STATUS', '허가 취소', '업체 관리자가 기존 허가를 취소한 상태', 'N', 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SG_REVOKED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'SG_ENDED', 'SUPPORT_GRANT_STATUS', '허가 종료', '지원 종료 또는 문의 해결로 접근이 종료된 상태', 'N', 5 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='SG_ENDED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'ACCESS_TYPE', NULL, '자료 접근 구분', '자료에 허용하는 작업의 종류', 'N', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='ACCESS_TYPE');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'ACCESS_READ', 'ACCESS_TYPE', '조회', '자료의 내용을 열람하는 작업', 'N', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='ACCESS_READ');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'ACCESS_WRITE', 'ACCESS_TYPE', '수정', '허가받은 자료의 내용을 변경하는 작업', 'N', 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='ACCESS_WRITE');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'MAP_SHARE_STATUS', NULL, '지도 공유 상태', '개인 지도 자료의 열람 요청 처리 상태', 'N', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='MAP_SHARE_STATUS');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'MS_REQUESTED', 'MAP_SHARE_STATUS', '열람 요청', '소유자에게 자료 열람을 요청한 상태', 'N', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='MS_REQUESTED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'MS_APPROVED', 'MAP_SHARE_STATUS', '열람 허가', '소유자가 열람을 허용한 상태', 'N', 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='MS_APPROVED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'MS_REJECTED', 'MAP_SHARE_STATUS', '열람 반려', '소유자가 열람을 허용하지 않은 상태', 'N', 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='MS_REJECTED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'MS_REVOKED', 'MAP_SHARE_STATUS', '허가 취소', '소유자가 기존 열람 허가를 해제한 상태', 'N', 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='MS_REVOKED');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'NOTIFICATION_CHANNEL', NULL, '알림 전달 경로', '업무 알림을 전달하는 수단', 'Y', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='NOTIFICATION_CHANNEL');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'NC_IN_APP', 'NOTIFICATION_CHANNEL', '서비스 내 알림', '이음의 헤더와 알림 목록에 표시하는 알림', 'Y', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='NC_IN_APP');
    INSERT INTO COMMON_CODE (CODE, PARENT_CODE, CODE_NAME, DESCRIPTION, USE_YN, SORT_ORDER)
    SELECT 'NC_EMAIL', 'NOTIFICATION_CHANNEL', '이메일', '이메일 주소로 전달하는 알림', 'N', 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM COMMON_CODE WHERE CODE='NC_EMAIL');
    UPDATE COMMON_CODE SET USE_YN='Y', UPDATED_AT=CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP)
    WHERE CODE IN ('TK_QUESTION', 'EV_LEAVE', 'POST_PUBLISHED', 'POST_REMOVED', 'FILE_REMOVED', 'FC_IMAGE', 'FC_DOCUMENT', 'FC_SPREADSHEET', 'FC_PRESENTATION', 'FC_ARCHIVE', 'FC_OTHER', 'EMP_REGULAR');
    SELECT COUNT(*) INTO v_count FROM COMMON_CODE WHERE CODE='PD_TRIAL';
    IF v_count <> 1 THEN RAISE_APPLICATION_ERROR(-20202,'PD_TRIAL 코드 확인 필요'); END IF;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO SP_IEUM_COMMON_PATCH;
        RAISE;
END;
/

